// The "How we know" methodology page in every language. Numbers come from RULES so the
// page always states the rules the pipeline actually applies (CLAUDE.md: change both together).
import { RULES } from '../../pipeline/config.ts';
import type { Lang } from './index.ts';

type R = typeof RULES;
export interface HowContent {
  title: string;
  description: string;
  eyebrow: string;
  h1: string;
  intro: string; // {n} = events tracked, {countries} = list
  pipelineH: string;
  steps: [string, string][];
  lastRun: string;
  vibesH: string;
  vibes: [string, string, string][]; // [label, sticker class, rule]
  stillOn: string;
  confidenceH: string;
  confidenceIntro: string;
  confidence: string[];
  confidenceOutro: string;
  readerH: string;
  readerIntro: string; // contains <a href="{add}">
  reader: string[];
  readerOutro: string;
  rulesH: string;
  rules: string[];
  limitsH: string;
  limits: string;
  correctionsH: string;
  corrections: string; // {email}
  creditsH: string;
  credits: string[]; // HTML
}

const pct = (x: number) => Math.round(x * 100);
const credits = (event: string, places: string, bounds: string, reporting: string) => [
  `${event}: <a class="prose-link" href="https://www.gdeltproject.org/" rel="noopener">The GDELT Project</a>`,
  `${places}: <a class="prose-link" href="https://www.geonames.org/" rel="noopener">GeoNames</a> (CC BY 4.0)`,
  `${bounds}: <a class="prose-link" href="https://www.naturalearthdata.com/" rel="noopener">Natural Earth</a>`,
  reporting,
];

const en = (R: R): HowContent => ({
  title: "How we know: LOUD's method for tracking protests",
  description: 'How LOUD finds, verifies and summarises protests: at least two independent newsrooms, a published confidence formula, automatic Serious Mode, human review and corrections.',
  eyebrow: 'The receipts for our receipts',
  h1: 'How we know',
  intro: "LOUD is a neutral protest tracker. The interface is playful; the facts are not. We don't take sides, we don't add adjectives, and we show you exactly where every line comes from. Right now we track <strong>{n}</strong> protests across {countries}.",
  pipelineH: 'From headline to card, every 4 hours',
  steps: [
    ['Listen', 'Every 4 hours we pull the GDELT 2.0 event feed (news articles its coders tag as protests, every 15 minutes, worldwide) plus RSS feeds from newsrooms in India, Europe, Ukraine, Russia, the Middle East, the US, Canada, Australia, New Zealand and Japan (GDELT misses most non-English reporting).'],
    ['Read', 'We open each article once and read it. Its text is used only in memory to judge and summarise. We never store or republish it.'],
    ['Judge', 'An AI classifier checks each article: is this a real, physical protest (not a diplomatic "protest", an opinion piece or an election rally), where did it happen, and is it new or part of one we already track?'],
    ['Place', 'The city is matched against the GeoNames gazetteer. Pins sit on the city centre, never on a street, venue or live route. If a place is ambiguous, we drop it rather than guess.'],
    ['Corroborate', `Nothing goes public until at least ${R.minPublishers} independent newsrooms report it. Sister titles from one media group count once; wire copy re-published by many sites counts once; syndication farms and aggregators don't count at all. When a fresh story has only one, we search news indexes for other newsrooms covering it; whatever we find goes through the same checks.`],
    ['Write', 'AI writes an original card from up to 10 reports: why, what they want, what changed, both sides, numbers only when a source states them, each with its source number.'],
    ['Check', 'Rules, not AI, set the vibe, "is it still on", Serious Mode and the confidence score. A number with no source is deleted. Banned words (like "mob" or "brave") send the card to a human.'],
    ['Review', `A human reviews anything involving deaths, injuries or mass arrests, the ${R.reviewTopN} biggest live protests, confidence below ${pct(R.reviewConfidence)}%, and sources that disagree. If no reviewer is on duty, a card flagged only for its score or size publishes once two independent newsrooms report it, with that score shown: at most ${R.twoSourcePerCountry} per country in ${R.twoSourceDays} days, the most-reported first. Cards involving harm or sources that disagree publish only once at least three independent newsrooms report them, and never with tone problems or low confidence.`],
    ['Translate', 'Each card is translated from the checked English into Spanish, French, German, Italian, Portuguese and Dutch; older cards keep the languages they already had (some also Hindi and Marathi). Facts, numbers and sources stay identical; only the language changes.'],
  ],
  lastRun: 'Last run',
  vibesH: 'What the vibe stickers mean',
  vibes: [
    ['Heating up', 's-heating-up', 'More reports in the last 24 hours than in the 24 hours before.'],
    ['Peak loud', 's-peak-loud', `In the top ${R.peakTopShare * 100}% of live protests by report volume (and at least ${R.minPeakVolume} reports in 48 hours).`],
    ['Cooling down', 's-cooling-down', 'Report volume flat or falling over the last 24 hours.'],
    ['Wrapped up', 's-wrapped-up', `Sources say it ended, was called off or demands were met, or there have been no new reports for ${R.wrapAfterHours} hours. One-day marches wrap at the end of their local day.`],
    ['Reader report', 's-reader', `Sent in by a reader through "Add a protest" and not confirmed by newsrooms yet. Shown after an automatic check, at least ${R.readerDelayMinutes} minutes after it was sent. Orange dashed card, no confidence score, not shown to search engines.`],
    ['Serious', 's-tense', `Any reported death, serious injury or hospitalisation, ${R.massInjuries}+ people injured, or ${R.massArrests}+ arrests or detentions, and protests that are about a death, suicide or sexual violence. The card turns grey and every joke is removed.`],
  ],
  stillOn: `<strong>Is it still on?</strong> YES means sources show it continuing (or it is a one-day action happening today, local time). NO says why: it ended, was called off, demands were met, or it went quiet for ${R.wrapAfterHours} hours. If our checks pause, pages say so at the top.`,
  confidenceH: 'The confidence score',
  confidenceIntro: 'A simple, published formula, not a black box:',
  confidence: [
    '2 independent newsrooms → 70%',
    '3 → 80% · 4 → 86% · 5 or more → 90%',
    '+5 points if one is an established national or wire newsroom',
    '−15 points if sources disagree on numbers or status (we show where)',
    '−5 points if an "ongoing" protest has had no report for 72 hours',
    'capped between 30% and 97%: we are never 100% sure',
  ],
  confidenceOutro: `Single-source news reports are never shown (reader reports are the labelled exception below). Below ${pct(R.reviewConfidence)}%, a card waits for a human's approval when a reviewer is on duty; otherwise it shows with its score, never with fewer than two newsrooms.`,
  readerH: 'Reader reports',
  readerIntro: 'Anyone can <a class="prose-link" href="{add}">add a protest</a>. Newsrooms miss things, especially small, local and rural protests. Reader reports are tips, and we label them that way.',
  reader: [
    `<strong>1. Wait.</strong> A report waits at least ${R.readerDelayMinutes} minutes, then our next check (every 4 hours) picks it up.`,
    '<strong>2. Basic checks.</strong> The country is one we track, the date is within the last 30 days or the next 2 weeks, and the city exists in GeoNames. Its pin sits on the city centre.',
    '<strong>3. Link check.</strong> If the reader shared a link, we open it and check that it is about the same protest.',
    '<strong>4. AI check.</strong> Is it a real protest action? Is it free of hate, calls for violence, spam and private people\'s names? It is rewritten in our neutral style. Claims of deaths, injuries, arrests or violence are held back until newsrooms confirm them.',
    '<strong>5. Duplicates.</strong> If we already track it, the report is added to that card instead of creating a new one.',
    `<strong>6. Upgrade or expire.</strong> Once ${R.minPublishers} independent newsrooms report it, it becomes a normal verified card marked "first flagged by a reader". Unconfirmed reports leave the site ${R.readerHideAfterDays} days after they wrap up.`,
  ],
  readerOutro: 'Reader reports have no confidence score, no share card, and are hidden from search engines and our news feeds. We never ask for your name or email. Your IP address is only used, scrambled with a daily key, to limit reports to 3 per day, and is never stored.',
  rulesH: 'House rules',
  rules: [
    '<strong>Both sides, with receipts.</strong> Every card states what protesters demand and what the authorities said, each linked to sources.',
    '<strong>No adjectives about people.</strong> No "brave", no "violent mob". Claims are attributed: "police said", "organisers claimed".',
    '<strong>No names or faces of protesters.</strong> We name organisations, parties and public officials, never ordinary participants, the injured or the detained.',
    '<strong>City-level locations only.</strong> Never exact gathering points or live movement.',
    '<strong>Original words only.</strong> Summaries are written fresh; we link out to the reporting and never copy text or photos.',
    "<strong>India's official borders.</strong> Maps use Natural Earth's India point-of-view boundaries, drawing Jammu &amp; Kashmir (including Gilgit-Baltistan and PoK), Ladakh (including Aksai Chin) and Arunachal Pradesh as part of India, per India's official position.",
    '<strong>Archive stays up.</strong> Wrapped-up protests keep their page so anyone can check what happened.',
  ],
  limitsH: 'What we can miss',
  limits: "We see what newsrooms report. Small or rural protests that get no coverage, or coverage only in languages our sources don't reach, can be missing or late. Crowd sizes are whatever sources state, and police and organisers often disagree. When they do, we show both. AI can make mistakes; that's why rules double-check it and humans review the sensitive cases.",
  correctionsH: 'Corrections',
  corrections: "Spotted something wrong? Email {email} with the page link and a source. We fix verified errors fast, and the page's \"updated\" time changes when we do.",
  creditsH: 'Data credits',
  credits: credits('Event discovery', 'Places', 'Boundaries (public domain, India point of view)', 'Reporting: the newsrooms linked on every card'),
});

